/**
 * The noise-reduction job (SPEC 12 §6.8).
 *
 * Run against the **real bundled ffmpeg**, because almost everything this file does is a claim
 * about that binary: which filters it has, whether the argument list is accepted, whether the file
 * it writes has samples in it. A mocked process would test the mock.
 *
 * The fixture is generated by the same binary — a tone with white noise on it — so the repository
 * carries no binary audio and the noise is real rather than described.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';
import { getFFmpegPath } from '@clipwright/media-core';
import {
  derivedDirectoryFor,
  noiseReductionCapabilities,
  resetNoiseReductionCapabilities,
  runNoiseReduction,
} from '../audio-enhance.js';

const FFMPEG = getFFmpegPath();

let workDir = '';
let noisyPath = '';
let derivedDir = '';
/*
  Resolved at module load, which is where the binary actually is — `getFFmpegPath` joins onto
  `process.cwd()`, and vitest runs the suite from the repository root. A `false` here skips rather
  than fails, because a machine without the bundled binary (a bare CI checkout of one package)
  cannot run these at all and should say so rather than report a broken denoiser.
*/
const hasFfmpeg = (() => {
  try {
    execFileSync(FFMPEG, ['-version'], { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
})();

/** Whether the bundled ffmpeg has the filter these tests need. */
function hasFilter(name: string): boolean {
  try {
    const out = execFileSync(FFMPEG, ['-hide_banner', '-filters'], { encoding: 'utf8' });
    return new RegExp(`\\s${name}\\s`).test(out);
  } catch {
    return false;
  }
}

beforeAll(() => {
  if (!hasFfmpeg || !hasFilter('afftdn')) return;
  workDir = mkdtempSync(join(tmpdir(), 'clipwright-enhance-'));
  derivedDir = join(workDir, 'derived');
  noisyPath = join(workDir, 'noisy.wav');
  execFileSync(FFMPEG, [
    '-hide_banner', '-nostdin', '-y',
    '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=48000:duration=1',
    '-f', 'lavfi', '-i', 'anoisesrc=color=white:sample_rate=48000:duration=1:amplitude=0.2',
    '-filter_complex', '[0:a]volume=0.25[a];[a][1:a]amix=inputs=2:duration=first',
    '-c:a', 'pcm_s16le',
    noisyPath,
  ]);
});

afterEach(() => resetNoiseReductionCapabilities());
afterAll(() => {
  if (workDir) rmSync(workDir, { recursive: true, force: true });
});

describe('where the cleaned copy goes', () => {
  /*
    Not a runnable test of the write — that is the job tests below. This is the arithmetic that
    decides *which disk* the app writes to, and getting it wrong puts a denoised copy in the user's
    camera card instead of the project. Pure, so it needs no ffmpeg and runs everywhere.
  */
  it('finds the derived directory from the proxy, three levels up', () => {
    /*
      The layout is `derived/proxy/<mediaId>/proxy.mp4`. Three levels up, not two — and the
      difference matters, because two levels lands on `derived/proxy`, which is a real directory
      that will happily accept the write. The bug is a file in the wrong place, not an error.
    */
    expect(
      derivedDirectoryFor({
        path: '/footage/cam/a.mov',
        proxyPath: '/project/derived/proxy/media-a/proxy.mp4',
      }),
    ).toBe('/project/derived');
  });

  it('finds it from the peaks when there is no proxy', () => {
    /*
      A media that did not need a proxy — a short clip, or `alwaysCreateProxy: false`. The peaks
      files sit directly in `derived/`, which is what `generatePeaks(audio, derivedDir)` writes.
    */
    expect(
      derivedDirectoryFor({
        path: '/footage/cam/a.mov',
        proxyPath: null,
        peaks256Path: '/project/derived/peaks256.bin',
      }),
    ).toBe('/project/derived');
  });

  it('never falls back to the footage directory when a derived artefact exists', () => {
    /*
      The failure this guards: a *reference* import whose source is on the user's disk. Writing
      beside the footage would succeed, look fine in the app, and leave files on a camera card.
    */
    const derived = derivedDirectoryFor({
      path: '/Volumes/CARD/DCIM/a.mov',
      proxyPath: '/project/derived/proxy/media-a/proxy.mp4',
    });
    expect(derived).not.toContain('Volumes');
    expect(derived).toBe('/project/derived');
  });

  it('falls back to the source’s directory only when nothing else is known', () => {
    /* Documented as the managed-import case; asserted so the fallback is a decision, not a drift. */
    expect(derivedDirectoryFor({ path: '/project/media/a.mov' })).toBe('/project/media');
  });
});

describe.runIf(hasFfmpeg)('probing the ffmpeg build', () => {
  it('finds the fft denoiser in the bundled binary', async () => {
    const capabilities = await noiseReductionCapabilities();
    expect(capabilities.afftdn).toBe(true);
  });

  it('reports RNNoise honestly, whichever way this build goes', async () => {
    /*
      The bundled ffmpeg is 4.1, which predates `arnndn`. Asserting `false` would turn red the day
      the binary is upgraded — the wrong signal for the wrong reason — so this asserts the probe
      against the binary rather than against a remembered answer, and separately that the two agree.
    */
    const capabilities = await noiseReductionCapabilities();
    expect(capabilities.arnndn).toBe(hasFilter('arnndn'));
  });

  it('probes once and remembers', async () => {
    /*
      `-filters` costs tens of milliseconds and the answer cannot change while the app runs. The
      second call must not spawn again — a per-job probe would be a process launch on every press of
      the button, for an answer that was already known.
    */
    const first = await noiseReductionCapabilities();
    const second = await noiseReductionCapabilities();
    expect(second).toBe(first);
  });
});

describe.runIf(hasFfmpeg && hasFilter('afftdn'))('running a job', () => {
  const base = () => ({
    mediaId: 'media-a',
    sourcePath: noisyPath,
    derivedDir,
    inUs: 0,
    durationUs: 1_000_000,
    strength: 'medium',
  });

  it('writes a denoised WAV under the media’s derived directory', async () => {
    const result = await runNoiseReduction(base());
    expect(result.ok).toBe(true);
    expect(result.outputPath).toContain('enhanced');
    expect(result.outputPath!.endsWith('.wav')).toBe(true);
    expect(existsSync(result.outputPath!)).toBe(true);
    expect(result.cached).toBeUndefined();
  });

  it('leaves the source untouched', async () => {
    /*
      The spec's "never destructive", checked the only way that means anything: by digest. A job
      that opened the source for writing would show up here even if the output were perfect.
    */
    const before = readFileSync(noisyPath).length;
    await runNoiseReduction(base());
    expect(readFileSync(noisyPath).length).toBe(before);
  });

  it('reuses the copy when the same settings are run again', async () => {
    const first = await runNoiseReduction(base());
    const second = await runNoiseReduction(base());
    expect(second.ok).toBe(true);
    expect(second.cached).toBe(true);
    expect(second.outputPath).toBe(first.outputPath);
  });

  it('makes a *different* file when the strength changes', async () => {
    /*
      The bug a cache keyed on the media alone would have: the user runs Low, finds it is not
      enough, runs High, and hears exactly the same thing.
    */
    const low = await runNoiseReduction({ ...base(), strength: 'low' });
    const high = await runNoiseReduction({ ...base(), strength: 'high' });
    expect(low.outputPath).not.toBe(high.outputPath);
    expect(existsSync(high.outputPath!)).toBe(true);
  });

  it('reports progress that ends at 100 and never goes backwards', async () => {
    /*
      A range no other test uses, so this one is a real encode. Every assertion about *running*
      would be vacuous against a cache hit, and the cache is keyed on the range — which is the
      property that makes this test independent without a teardown.
    */
    const percents: number[] = [];
    const result = await runNoiseReduction({
      ...base(),
      inUs: 100_000,
      durationUs: 700_000,
      onProgress: (progress) => percents.push(progress.percent),
    });
    expect(result.ok).toBe(true);
    expect(percents.length).toBeGreaterThan(0);
    expect(percents.at(-1)).toBe(100);
    for (let index = 1; index < percents.length; index += 1) {
      expect(percents[index]!).toBeGreaterThanOrEqual(percents[index - 1]!);
    }
  });

  it('tells the user the original is untouched', async () => {
    /*
      The spec's warning is a sentence the UI has to be able to earn, not a tooltip. A fresh
      range again, because the *cached* message deliberately says something different — that the
      copy was reused — and asserting this against a cache hit would be asserting the wrong string.
    */
    const result = await runNoiseReduction({ ...base(), inUs: 200_000, durationUs: 600_000 });
    expect(result.ok).toBe(true);
    expect(result.message.toLowerCase()).toContain('original');
    expect(result.message.toLowerCase()).toContain('compare');
  });

  it('refuses a strength it does not understand rather than choosing one', async () => {
    const result = await runNoiseReduction({ ...base(), strength: 'ludicrous' });
    expect(result.ok).toBe(false);
    expect(result.plan.refusal).toBe('unknown-strength');
    expect(result.outputPath).toBeUndefined();
  });

  it('refuses a clip with no audio', async () => {
    const result = await runNoiseReduction({ ...base(), hasAudio: false });
    expect(result.ok).toBe(false);
    expect(result.plan.refusal).toBe('no-audio');
  });

  it('throws — rather than returning a refusal — when the source file is gone', async () => {
    /*
      This is the one failure the user cannot fix from the panel: the plan was valid and the file
      is not there, so the answer is a relink, which is a different surface. Returning `ok: false`
      would present it as a settings problem.
    */
    await expect(
      runNoiseReduction({ ...base(), sourcePath: join(workDir, 'gone.wav') }),
    ).rejects.toThrow(/missing/i);
  });

  it('stops when the job is cancelled', async () => {
    /*
      An already-aborted signal. The range is fresh so a process is actually spawned — against a
      cache hit the job would return the file before consulting the signal, and the test would
      pass while proving nothing about cancellation.
    */
    const controller = new AbortController();
    controller.abort();
    await expect(
      runNoiseReduction({
        ...base(),
        inUs: 300_000,
        durationUs: 500_000,
        signal: controller.signal,
      }),
    ).rejects.toThrow();
  });
});
